/*!
 * \file kernel_operator.h
 * \brief
 */
#ifndef ASCENDC_MODULE_OPERATOR_H
#define ASCENDC_MODULE_OPERATOR_H

#include "kernel_tpipe_impl.h"
#include "kernel_tensor_impl.h"
#include "kernel_type.h"
#include "kernel_operator_intf.h"

#endif // ASCENDC_MODULE_OPERATOR_H

__aicore__ inline __inout_pipe__(MTE2) void DataCopyPad(const LocalTensor<T> &dst,
