17	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
18	
19	at::Tensor split(const at::Tensor &self, int64_t split_size_or_sections, int64_t dim)
20	{
21	    // ---- input validation ----
22	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
23	                "split: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
24	    TORCH_CHECK(self.is_contiguous(), "split: input tensor must be contiguous");
25	
26	    at::Tensor output = at::empty_like(self);
27	
28	    int64_t totalLength = self.numel();
29	    if (totalLength == 0) {
30	        return output;
31	    }
32	
33	    int64_t dtypeSize = self.element_size();
34	
35	    // ---- get hardware params ----
36	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
37	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
38	    uint64_t ubSize;
39	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
40	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
41	
42	    // ---- Block level tiling (inter-core split, Cache Line aligned) ----
43	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
44	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
45	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
46	
47	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
48	    int64_t formerNum = usedCoreNum - 1;
49	    int64_t formerLength = totalLengthCoreAlign;
50	    int64_t tailLength = totalLength - formerNum * formerLength;
51	
52	    // ---- UB level tiling (intra-core split) ----
53	    // Split is pure data movement (single input, single output, no compute buffer)
54	    // float32: 2 queues * 2(double buf) * 4B = 16  => coefficient = 16 / 4 = 4 elements factor
55	    // float16/bf16: 2 queues * 2(double buf) * 2B = 8  => coefficient = 8 / 2 = 4 elements factor
56	    // So bufferCoefficient in elements = 4 for all dtypes
57	    int64_t bufferCoefficient = 4;
58	    int64_t maxTileElements = ubSizeLimit / (bufferCoefficient * dtypeSize);
59	    if (maxTileElements < 1) {
60	        maxTileElements = 1;
61	    }
62	    int64_t alignElements = 32 / dtypeSize;
63	    if (alignElements < 1) {
64	        alignElements = 1;
65	    }
66	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
67	    if (tileLength < 1) {
68	        tileLength = alignElements;
69	    }
70	
71	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
72	
73	    // All params must be left-values
74	    int64_t formerNumL = formerNum;
75	    int64_t formerLengthL = formerLength;
76	    int64_t tailLengthL = tailLength;
77	    int64_t tileLengthL = tileLength;
78	    int64_t dtypeSizeL = dtypeSize;
79	
80	    EXEC_KERNEL_CMD(split, blockDim,
81	                    self, output,
82	                    formerNumL, formerLengthL, tailLengthL, tileLengthL, dtypeSizeL);
83	
84	    return output;
85	}
86	
87	}  // namespace ascend_kernel
